"""Implement a Priority Queue — min heap over (priority, sequence, value).

The monotonically increasing sequence number breaks ties, which is what makes
the queue stable for equal priorities.

Time: O(log n) push/pop   Space: O(n)
"""


class PriorityQueue:
    def __init__(self):
        self._data = []
        self._seq = 0

    def _sift_up(self, i: int) -> None:
        while i > 0:
            parent = (i - 1) // 2
            if self._data[i] >= self._data[parent]:
                break
            self._data[i], self._data[parent] = self._data[parent], self._data[i]
            i = parent

    def _sift_down(self, i: int) -> None:
        n = len(self._data)
        while True:
            smallest = i
            for child in (2 * i + 1, 2 * i + 2):
                if child < n and self._data[child] < self._data[smallest]:
                    smallest = child
            if smallest == i:
                return
            self._data[i], self._data[smallest] = self._data[smallest], self._data[i]
            i = smallest

    def push(self, value: int, priority: int) -> None:
        self._data.append((priority, self._seq, value))
        self._seq += 1
        self._sift_up(len(self._data) - 1)

    def pop(self) -> int:
        if not self._data:
            return -1
        top = self._data[0]
        last = self._data.pop()
        if self._data:
            self._data[0] = last
            self._sift_down(0)
        return top[2]

    def peek(self) -> int:
        return self._data[0][2] if self._data else -1

    def isEmpty(self) -> bool:
        return not self._data
